        %timefield%: @timestamp
        index: traces-apm*
        body: {
          size: 0
          aggs: {
            services: {
              terms: {
                field: ci.name
                size: 5000
                order: {
                  _key: asc
                }
              }
              aggs: {
                total: {
                  filter: {
                    bool: {
                      must_not: [
                        {
                          wildcard: {
                            transaction.name: google*
                          }
                        }
                      ]
                    }
                  }
                }
                success: {
                  filter: {
                    bool: {
                      must: [
                        {
                          term: {
                            event.outcome: success
                          }
                        }
                      ]
                      must_not: [
                        {
                          wildcard: {
                            transaction.name: google*
                          }
                        }
                      ]
                    }
                  }
                }
                error_5xx: {
                  filter: {
                    bool: {
                      must: [
                        {
                          range: {
                            http.response.status_code: {
                              gte: 500
                            }
                          }
                        }
                      ]
                      must_not: [
                        {
                          wildcard: {
                            transaction.name: google*
                          }
                        }
                      ]
                    }
                  }
                }
              }
            }
          }
        }
      }
      format: {
        property: aggregations.services.buckets
      }
      transform: [
        {
          type: formula
          as: appName
          expr: datum.key
        }
        {
          type: formula
          as: availability
          expr: (datum.total.doc_count > 0) ? ((datum.success.doc_count + datum.error_5xx.doc_count) / datum.total.doc_count) * 100 : null
        }
        {
          type: formula
          as: status
          expr: datum.availability >= 99.5 ? 'Healthy' : datum.availability >= 99.0 ? 'Warning' : 'Critical'
        }
        {
          type: formula
          as: sortOrder
          expr: datum.status=='Healthy' ? 1 : datum.status=='Warning' ? 2 : 3
        }
      ]
    }
    {
      name: distribution
      source: services
      transform: [
        {
          type: aggregate
          groupby: [
            status
            sortOrder
          ]
          ops: [
            count
            values
          ]
          fields: [
            null
            appName
          ]
          as: [
            count
            apps
          ]
        }
        {
          type: formula
          as: appList
          expr: join(pluck(datum.apps,'appName'),' • ')
        }
      ]
    }
    {
      name: totals
      source: distribution
      transform: [
        {
          type: aggregate
          ops: [
            sum
          ]
          fields: [
            count
          ]
          as: [
            totalApps
          ]
        }
      ]
    }
    {
      name: segments
      source: distribution
      transform: [
        {
          type: formula
          as: totalApps
          expr: data('totals')[0].totalApps
        }
        {
          type: formula
          as: pct
          expr: datum.count / datum.totalApps
        }
        {
          type: stack
          field: count
          sort: {
            field: sortOrder
            order: ascending
          }
        }
      ]
    }
  ]
  scales: [
    {
      name: x
      type: linear
      domain: [
        0
        {
          signal: data('totals')[0].totalApps
        }
      ]
      range: [
        10
        600
      ]
    }
    {
      name: color
      type: ordinal
      domain: [
        Healthy
        Warning
        Critical
      ]
      range: [
        "#3DDC84"
        "#F2C94C"
        "#EB5757"
      ]
    }
  ]
  marks: [
