          }
        }
      }
    }
    {
      type: rect
      from: {
        data: segments
      }
      encode: {
        enter: {
          y: {
            value: 45
          }
          height: {
            value: 28
          }
          cornerRadius: {
            value: 4
          }
          fill: {
            scale: color
